const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Lake Okeechobee geometry (approximate boundary)
  const lakeCenter = ee.Geometry.Point([-80.8, 27.0]);
  const lake = lakeCenter.buffer(25000); // ~25km radius to cover the lake

  // 2. Date range
  const startDate = '2023-06-11';
  const endDate = '2023-06-13';

  // 3. Load Sentinel-2 data
  const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lake)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const imageCount = s2.size().getInfo();
  console.log(`Images found: ${imageCount}`);

  if (imageCount === 0) {
    console.log('No Sentinel-2 images found for the date range.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Cloud masking function
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBit = 1 << 10;
    const cirrusBit = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBit).eq(0)
      .and(qa.bitwiseAnd(cirrusBit).eq(0));
    return image.updateMask(mask);
  }

  // 5. Calculate NDCI (Normalized Difference Chlorophyll Index)
  function addNDCI(image) {
    const ndci = image.normalizedDifference(['B5', 'B4']).rename('NDCI');
    return image.addBands(ndci);
  }

  // 6. Process imagery
  const processed = s2.map(maskClouds).map(addNDCI).median();

  // 7. Count total valid pixels
  const totalPixels = processed.select('NDCI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lake,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDCI');

  const totalCount = totalPixels.getInfo();
  console.log(`Total valid pixels: ${totalCount}`);

  if (totalCount === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 8. Threshold for cyanobacteria detection (NDCI > 0.1 indicates potential algae)
  const cyanoThreshold = 0.1;
  const cyanoBacteria = processed.select('NDCI').gt(cyanoThreshold);

  // 9. Count cyanobacteria pixels
  const cyanoPixels = cyanoBacteria.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lake,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDCI');

  const cyanoCount = cyanoPixels.getInfo();

  if (cyanoCount === null || totalCount === null) {
    console.log('Calculation failed - returned null values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 10. Calculate percentage
  const percentage = (cyanoCount / totalCount) * 100;
  console.log(`Cyanobacteria pixels: ${cyanoCount}`);
  console.log(`Coverage percentage: ${percentage.toFixed(2)}%`);

  // 11. Determine answer
  if (percentage > 30) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
